INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (1,'gujarat','Gujarat','State','West','Kutch, Gir, Statue of Unity','<p>The state runs from the Pakistani border at Kutch to the forested hills of the Dangs, and the distance between them is cultural as much as physical. In the north-west you sleep in a mud bhunga on salt flats that stretch flat to the horizon; six hours south you are in a Portuguese-era port town eating fish thali.</p><p>Distances are long but the roads are among India’s best, which makes Gujarat one of the few states where a self-drive loop genuinely beats the trains.</p>','Come in the four months after Diwali. Everything you came for is open, and none of it is 44°C.','Nisha Thakkar · Gujarat editor','Nov – Feb','7 – 10','₹3,500','4 airports',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (2,'rajasthan','Rajasthan','State','West','Jaipur, Udaipur, Jaisalmer','<p>Nine former kingdoms, each with a fort on a hill and a city grown up beneath it. The distances between them are the point — the desert changes colour twice a day and the road is where you see it.</p><p>Jaipur, Jodhpur, Udaipur and Jaisalmer form the standard circuit. Bundi, Shekhawati and Bikaner are where the people who came back go.</p>','Everyone does the same four cities. Add one nobody mentions and the trip changes completely.','Arjun Rao · North India editor','Oct – Mar','10 – 14','₹4,000','3 airports',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (3,'maharashtra','Maharashtra','State','West','Mumbai, Ajanta, Konkan coast','<p>Mumbai is the obvious entry, but the state behind it holds the Ajanta and Ellora caves, the Sahyadri hill forts and six hundred kilometres of Konkan coastline that almost nobody visits.</p><p>The monsoon here is a destination in itself — the Western Ghats between June and September are a different country.</p>','Leave Mumbai on the third day. The state starts where the suburbs stop.','Priya Menon · West India editor','Nov – Feb','7 – 9','₹3,800','3 airports',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (4,'goa','Goa','State','West','Beaches, Portuguese quarters','<p>Two Goas: the beach strip everyone pictures, and the interior of Portuguese churches, spice plantations and Latin Quarter houses in Fontainhas that most visitors never reach.</p><p>North is busy and cheap, south is quiet and expensive, and the difference is roughly forty minutes of driving.</p>','Stay inland one night. It costs less and you finally hear the birds.','Priya Menon · West India editor','Nov – Feb','4 – 6','₹3,200','1 airport',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (5,'kerala','Kerala','State','South','Backwaters, Munnar, Fort Kochi','<p>Backwaters at sea level, tea at fifteen hundred metres, and a coastline that has been trading with the world for two thousand years. Kerala is narrow enough to cross in a morning and varied enough to fill a fortnight.</p><p>The state has India’s highest literacy and its most organised tourism, which shows in how easy independent travel is here.</p>','Skip the private houseboat. The public ferry from Alappuzha costs ₹40 and goes the same way.','Meera Joshi · South India editor','Sep – Mar','8 – 10','₹3,600','4 airports',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (6,'tamil-nadu','Tamil Nadu','State','South','Madurai, Ooty, Mahabalipuram','<p>The temple state — gopurams the height of office blocks, still in daily use after eight hundred years. Madurai, Thanjavur, Chidambaram and Srirangam are the four that justify the trip.</p><p>The Nilgiris provide the relief: Ooty and Kodaikanal sit two thousand metres above the plains, reachable by a mountain railway that has run since 1908.</p>','Go to one temple at 5am. It is a different building when it is working rather than being visited.','Meera Joshi · South India editor','Nov – Feb','9 – 12','₹3,200','4 airports',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (7,'karnataka','Karnataka','State','South','Hampi, Coorg, Mysuru','<p>Hampi alone justifies the state — fourteen square miles of boulder-strewn ruins that was the richest city in the world in 1500. Add the Mysuru palace, the Coorg coffee hills and a long undeveloped coastline.</p><p>Bengaluru is the entry point and worth two days for the food, though the traffic is genuinely as bad as reported.</p>','Hampi needs three days, not one. The far side of the river is the half people miss.','Devang Patel · Heritage editor','Oct – Feb','8 – 10','₹3,400','3 airports',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (8,'telangana','Telangana','State','South','Hyderabad, Ramoji, Warangal','<p>Hyderabad is the reason to come — Golconda, the Charminar, the Chowmahalla Palace and a biryani tradition that people fly in for.</p><p>Warangal and the Ramappa temple, a UNESCO site since 2021, are a comfortable day trip from the city.</p>','Eat the biryani where the queue is, not where the review said.','Arjun Rao · North India editor','Oct – Feb','4 – 6','₹3,000','1 airport',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (9,'andhra-pradesh','Andhra Pradesh','State','South','Tirupati, Araku, Vizag','<p>Tirupati draws more pilgrims than anywhere else on earth, but the state also has the Araku valley railway, the Borra caves and a long stretch of quiet Bay of Bengal coast at Visakhapatnam.</p><p>Vijayawada and Amaravati carry the Buddhist history most visitors do not expect.</p>','The Araku train out of Visakhapatnam is the best five hours of rail in south India.','Meera Joshi · South India editor','Oct – Mar','5 – 7','₹2,800','2 airports',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (10,'puducherry','Puducherry','UT','South','French quarter, Auroville','<p>A French colonial grid on the Coromandel coast, with yellow-walled streets, a seafront promenade closed to traffic each evening, and Auroville ten kilometres inland.</p><p>Small enough to walk, and best treated as a slow two days rather than a stop.</p>','The promenade closes to cars at six. That hour is the whole town at its best.','Meera Joshi · South India editor','Nov – Feb','2 – 3','₹3,000','1 airport',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (11,'himachal-pradesh','Himachal Pradesh','State','North','Shimla, Manali, Spiti','<p>Two distinct halves: the green, accessible lower Himalaya of Shimla, Dharamshala and Manali, and the high desert of Spiti and Lahaul behind the passes.</p><p>Spiti is only reachable between June and September. Planning around that single fact decides the whole trip.</p>','Spiti is not an extension of Manali. Give it its own week or do not go.','Arjun Rao · North India editor','Mar – Jun, Sep – Nov','7 – 12','₹2,800','2 airports',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (12,'uttarakhand','Uttarakhand','State','North','Rishikesh, Nainital, Char Dham','<p>The Ganga leaves the mountains at Rishikesh, and above it sit the four Char Dham shrines, Valley of Flowers and Corbett, India’s oldest national park.</p><p>Yoga and rafting have made Rishikesh famous; the state’s high meadows are the better reason to come.</p>','Valley of Flowers has a six-week window. Everything else can wait.','Nisha Thakkar · Mountains editor','Mar – Jun, Sep – Nov','7 – 10','₹2,900','1 airport',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (13,'punjab','Punjab','State','North','Amritsar and the Golden Temple','<p>Amritsar carries the Golden Temple, open all night and serving free food to fifty thousand people a day, plus the Partition Museum and the Wagah border ceremony.</p><p>The countryside between Amritsar and Chandigarh is flat, green and full of dhabas that do one thing exceptionally well.</p>','Go to the Golden Temple at four in the morning. You will not forget it.','Arjun Rao · North India editor','Oct – Mar','3 – 4','₹2,600','1 airport',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (14,'ladakh','Ladakh','UT','North','High-altitude desert, Pangong Tso','<p>A cold desert at three and a half thousand metres, with Tibetan Buddhist monasteries on ridgelines and lakes that change colour through the day.</p><p>Altitude is the planning constraint: two days acclimatising in Leh before anything else, without exception.</p>','Two days doing nothing in Leh is not wasted time. It is the trip working.','Nisha Thakkar · Mountains editor','Jun – Sep','8 – 12','₹4,200','1 airport',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (15,'jammu-kashmir','Jammu & Kashmir','UT','North','Dal Lake, Gulmarg, Pahalgam','<p>Srinagar sits on a lake with houseboats that have not changed in a century, ringed by meadows at Gulmarg, Pahalgam and Sonamarg.</p><p>Check current advisories before booking. Conditions vary by district and change.</p>','A shikara at dawn on Dal Lake, before the market boats. That is the memory.','Nisha Thakkar · Mountains editor','Apr – Oct','6 – 8','₹3,400','2 airports',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (16,'delhi','Delhi','UT','North','Capital, Mughal monuments','<p>Eight cities built on the same ground. Mughal Delhi around the Red Fort and Jama Masjid, colonial Delhi in Lutyens’ avenues, and the tombs of Mehrauli older than both.</p><p>The metro is excellent and makes the distances manageable in a way taxis do not.</p>','Humayun’s Tomb at opening is empty. The Taj gets the crowds; this gets the light.','Devang Patel · Heritage editor','Oct – Mar','3 – 4','₹3,200','1 airport',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (17,'haryana','Haryana','State','North','Kurukshetra, Sultanpur, Morni','<p>Mostly passed through on the way to somewhere else, which is a shame — Kurukshetra carries the Mahabharata sites and Sultanpur is a serious birding lake an hour from Delhi.</p><p>Morni Hills gives the state its only hill station, modest but genuinely quiet.</p>','Sultanpur in January, at seven in the morning, is as good as birding gets near a capital.','Priya Menon · West India editor','Oct – Mar','2 – 3','₹2,400','1 airport',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (18,'uttar-pradesh','Uttar Pradesh','State','Central','Taj Mahal, Varanasi, Ayodhya','<p>The Taj is here, and so is Varanasi, and between them sit Fatehpur Sikri, Sarnath, Lucknow’s Awadhi kitchens and the ghats at Chitrakoot.</p><p>It is the most-visited state in India and still the one where a day’s drive finds something nobody photographs.</p>','Varanasi at 5am from a boat. Everything else in the state is a supporting act.','Devang Patel · Heritage editor','Oct – Mar','8 – 12','₹2,700','3 airports',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (19,'madhya-pradesh','Madhya Pradesh','State','Central','Khajuraho, Bandhavgarh, Orchha','<p>The best tiger reserves in India — Bandhavgarh, Kanha, Pench — plus Khajuraho, Sanchi and the riverside temples of Orchha and Maheshwar.</p><p>Distances are large and the roads are better than expected. A driver for the week is the normal approach.</p>','Two safaris a day for three days. One is a lottery; six is a reasonable chance.','Nisha Thakkar · Wildlife editor','Oct – Mar','8 – 11','₹3,000','3 airports',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (20,'chhattisgarh','Chhattisgarh','State','Central','Chitrakote falls, Bastar','<p>Chitrakote, India’s widest waterfall, and the Bastar region’s weekly tribal markets, which remain one of the least-packaged experiences in the country.</p><p>Infrastructure is thin. Go with a local operator or be comfortable improvising.</p>','The Bastar haats are the reason to come, and they only happen on their own day.','Devang Patel · Heritage editor','Oct – Mar','5 – 7','₹2,400','1 airport',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (21,'west-bengal','West Bengal','State','East','Kolkata, Darjeeling, Sundarbans','<p>Kolkata for the colonial architecture, the food and the bookshops; Darjeeling for tea and the toy train; the Sundarbans for mangrove tiger country reachable only by boat.</p><p>Durga Puja in autumn turns the whole city into an open-air exhibition and is worth planning a year around.</p>','Kolkata is a walking city disguised as a traffic jam. Start at College Street.','Meera Joshi · East India editor','Oct – Mar','7 – 10','₹2,900','2 airports',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (22,'odisha','Odisha','State','East','Puri, Konark, Chilika','<p>The Sun Temple at Konark, the Jagannath temple at Puri, and Chilika, Asia’s largest brackish lagoon, full of migratory birds and a resident dolphin population.</p><p>The Buddhist sites at Ratnagiri and Udayagiri are excellent and almost empty.</p>','Konark deserves a guide. Without one it is a beautiful building you do not understand.','Devang Patel · Heritage editor','Oct – Mar','6 – 8','₹2,500','1 airport',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (23,'bihar','Bihar','State','East','Bodh Gaya, Nalanda','<p>Bodh Gaya is where the Buddha reached enlightenment, and remains a working pilgrimage centre with monasteries built by a dozen countries.</p><p>Nalanda, the ruined university, and Rajgir’s hot springs complete a compact and historically dense circuit.</p>','Bodh Gaya in December, when the monasteries are full and the winter teachings run.','Meera Joshi · East India editor','Oct – Mar','4 – 6','₹2,200','1 airport',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (24,'jharkhand','Jharkhand','State','East','Betla, Netarhat, waterfalls','<p>Forest, plateau and waterfalls — Hundru, Dassam and Jonha are all within an hour of Ranchi, and Betla National Park holds elephants and the occasional tiger.</p><p>Netarhat is the state’s hill station and one of the quieter sunrises in eastern India.</p>','Go just after the monsoon. The falls are running and the plateau is green.','Meera Joshi · East India editor','Oct – Mar','4 – 5','₹2,200','1 airport',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (25,'sikkim','Sikkim','State','East','Gangtok, Kanchenjunga views','<p>India’s first fully organic state, with Kanchenjunga visible from the capital on a clear morning and monasteries at Rumtek and Pemayangtse.</p><p>North Sikkim needs a permit arranged in advance and is worth the paperwork.</p>','Clear mornings in October and November. That is when the mountain shows itself.','Nisha Thakkar · Mountains editor','Mar – May, Oct – Dec','5 – 7','₹3,000','1 airport',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (26,'assam','Assam','State','North-East','Kaziranga, Majuli, tea gardens','<p>Kaziranga holds two thirds of the world’s one-horned rhinos. Majuli is the largest river island in the world, with Vaishnavite monasteries that have been there for five centuries.</p><p>The Brahmaputra defines the state, and a night on it is the best way to understand why.</p>','Kaziranga on elephant-back at dawn, then the same park by jeep at four. Both, not either.','Nisha Thakkar · Wildlife editor','Nov – Apr','5 – 7','₹2,800','2 airports',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (27,'meghalaya','Meghalaya','State','North-East','Cherrapunji, living root bridges','<p>The wettest place on earth, with living root bridges grown from ficus over decades and caves that run for kilometres under the plateau.</p><p>The double-decker root bridge at Nongriat is a three-thousand-step descent and worth every one.</p>','Stay a night at Nongriat. The day-trippers leave and the valley is yours.','Nisha Thakkar · Mountains editor','Oct – Apr','5 – 6','₹2,900','1 airport',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (28,'arunachal-pradesh','Arunachal Pradesh','State','North-East','Tawang, Ziro valley','<p>Tawang holds the largest monastery in India outside Tibet, at three thousand metres and reached over the Sela Pass.</p><p>The Ziro valley, with its Apatani villages and September music festival, is the other reason to come.</p>','The road to Tawang is the destination. Give it two days each way.','Nisha Thakkar · Mountains editor','Oct – Apr','7 – 10','₹3,200','1 airport',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (29,'nagaland','Nagaland','State','North-East','Hornbill festival, Khonoma','<p>The Hornbill Festival in the first week of December brings all sixteen tribes to Kisama, and is the single best week to visit.</p><p>Khonoma, the green village, has banned hunting and rebuilt itself around conservation tourism.</p>','Hornbill is extraordinary and completely booked. Reserve in August.','Meera Joshi · East India editor','Oct – Apr','5 – 7','₹2,800','1 airport',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (30,'manipur','Manipur','State','North-East','Loktak Lake, Imphal','<p>Loktak Lake carries the world’s only floating national park, where the phumdi islands support a population of endangered brow-antlered deer.</p><p>Imphal’s Ima Keithel is a market of five thousand stalls run entirely by women.</p>','Ima Keithel at nine in the morning. There is nothing else like it in India.','Meera Joshi · East India editor','Oct – Mar','4 – 6','₹2,600','1 airport',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (31,'mizoram','Mizoram','State','North-East','Aizawl, Phawngpui','<p>Ridge-top villages, near-total literacy and Phawngpui, the blue mountain, on the Myanmar border.</p><p>Sunday is genuinely observed — plan travel around it.</p>','Aizawl is built along a ridge. Walk it once end to end to understand the place.','Meera Joshi · East India editor','Oct – Mar','4 – 5','₹2,600','1 airport',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (32,'tripura','Tripura','State','North-East','Ujjayanta Palace, Unakoti','<p>Unakoti’s rock-cut reliefs are carved into a hillside and largely unvisited; Neermahal sits in the middle of a lake.</p><p>Agartala is compact and the palace museum is better than its reputation.</p>','Unakoti during the April festival, or completely alone in December. Both work.','Devang Patel · Heritage editor','Oct – Mar','3 – 5','₹2,400','1 airport',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (33,'andaman-nicobar','Andaman & Nicobar','UT','South','Havelock, Neil, diving','<p>The best diving in India, off Havelock and Neil, with visibility that holds through the dry season and a marine park at Wandoor.</p><p>Ferries book out weeks ahead in season — that, not flights, is the bottleneck.</p>','Book the inter-island ferries before the hotel. They sell out first.','Meera Joshi · South India editor','Nov – Apr','6 – 8','₹4,500','1 airport',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (34,'lakshadweep','Lakshadweep','UT','South','Atolls, lagoons','<p>Thirty-six coral islands, ten inhabited, with permits required and visitor numbers deliberately capped.</p><p>Agatti and Bangaram take most visitors; the lagoon water is the clearest in the country.</p>','Permits take weeks. Start the paperwork before you dream about the water.','Meera Joshi · South India editor','Oct – Mar','4 – 6','₹5,000','1 airport',true);
INSERT INTO states (id,slug,name,kind,region,tagline,intro,quote,quote_by,best_season,days_needed,daily_budget,airports,published) VALUES (35,'chandigarh','Chandigarh','UT','North','Le Corbusier city, Rock Garden','<p>Le Corbusier’s planned capital, with the Capitol Complex a UNESCO site and Nek Chand’s Rock Garden built secretly from industrial waste over eighteen years.</p><p>Flat, walkable and easy — a genuine two-day city.</p>','The Capitol Complex needs a free permit and a guide. Arrange it the day before.','Devang Patel · Heritage editor','Oct – Mar','2','₹2,800','1 airport',true);
INSERT INTO cities (id,slug,state_id,name,tagline,intro,best_season,days_needed,daily_budget,nearest_airport,published) VALUES (1,'ahmedabad',1,'Ahmedabad','India’s first UNESCO World Heritage City','Six hundred years of stepwells, pols and mill-owner mansions, plus the best vegetarian street food in the country.','Nov – Feb','2 – 3','₹2,800','AMD, 9 km',true);
INSERT INTO cities (id,slug,state_id,name,tagline,intro,best_season,days_needed,daily_budget,nearest_airport,published) VALUES (2,'bhuj',1,'Bhuj','Gateway to the Rann and the craft villages','The base for the white desert, the Banni grasslands and a dozen villages where Ajrakh, Rogan and bandhani are still made by hand.','Nov – Feb','3 – 4','₹2,600','BHJ, 5 km',false);
INSERT INTO cities (id,slug,state_id,name,tagline,intro,best_season,days_needed,daily_budget,nearest_airport,published) VALUES (3,'vadodara',1,'Vadodara','Palaces, art school, Navratri capital','The Gaekwad capital, with a palace four times the size of Buckingham and the country’s most serious fine art faculty.','Nov – Feb','2','₹2,400','BDQ, 6 km',false);
INSERT INTO cities (id,slug,state_id,name,tagline,intro,best_season,days_needed,daily_budget,nearest_airport,published) VALUES (4,'surat',1,'Surat','Diamonds, textiles and the best locho','Ninety per cent of the world’s diamonds are cut here, and the street food is the reason people from Ahmedabad drive down.','Nov – Feb','2','₹2,500','STV, 11 km',false);
INSERT INTO cities (id,slug,state_id,name,tagline,intro,best_season,days_needed,daily_budget,nearest_airport,published) VALUES (5,'dwarka',1,'Dwarka','Krishna’s city, and the ferry to Bet Dwarka','One of the four Char Dham sites, on the westernmost point of the mainland, with a temple that has stood in some form for two millennia.','Oct – Mar','2','₹2,000','JGA, 137 km',false);
INSERT INTO cities (id,slug,state_id,name,tagline,intro,best_season,days_needed,daily_budget,nearest_airport,published) VALUES (6,'somnath',1,'Somnath','Temple on the sea, rebuilt six times','Destroyed and rebuilt through a thousand years of history, now facing the Arabian Sea with an evening aarti worth timing your day around.','Oct – Mar','1 – 2','₹2,000','DIU, 90 km',false);
INSERT INTO cities (id,slug,state_id,name,tagline,intro,best_season,days_needed,daily_budget,nearest_airport,published) VALUES (7,'junagadh',1,'Junagadh','Gir’s base, plus the Girnar climb','Ten thousand steps up Girnar at dawn, and the only place on earth with wild Asiatic lions an hour down the road.','Dec – Mar','2 – 3','₹2,200','RAJ, 100 km',false);
INSERT INTO cities (id,slug,state_id,name,tagline,intro,best_season,days_needed,daily_budget,nearest_airport,published) VALUES (8,'rajkot',1,'Rajkot','Saurashtra’s centre, and Gandhi’s school','A working city rather than a sight, but the food is the best in Saurashtra and Gandhi’s childhood home is here.','Nov – Feb','1 – 2','₹2,200','RAJ, 4 km',false);
INSERT INTO cities (id,slug,state_id,name,tagline,intro,best_season,days_needed,daily_budget,nearest_airport,published) VALUES (9,'jaipur',2,'Jaipur','Pink city, Amber Fort, block printing','A planned city from 1727 with a fort above it, the best shopping in north India and an observatory that still tells the time.','Oct – Mar','3','₹3,200','JAI, 13 km',false);
INSERT INTO cities (id,slug,state_id,name,tagline,intro,best_season,days_needed,daily_budget,nearest_airport,published) VALUES (10,'udaipur',2,'Udaipur','Lakes, palaces, and the best sunsets','Built around a chain of artificial lakes, with a palace complex on the shore and another in the middle of the water.','Sep – Mar','2 – 3','₹3,400','UDR, 22 km',false);
INSERT INTO cities (id,slug,state_id,name,tagline,intro,best_season,days_needed,daily_budget,nearest_airport,published) VALUES (11,'jodhpur',2,'Jodhpur','Blue city under Mehrangarh','The fort is the finest in India and the old city beneath it is painted blue for reasons nobody fully agrees on.','Oct – Mar','2','₹2,800','JDH, 5 km',false);
INSERT INTO cities (id,slug,state_id,name,tagline,intro,best_season,days_needed,daily_budget,nearest_airport,published) VALUES (12,'jaisalmer',2,'Jaisalmer','A living fort in the Thar','One of the few forts in the world people still live inside, with the desert starting where the walls end.','Nov – Feb','2 – 3','₹2,600','JSA, 17 km',false);
