INSERT INTO attractions (id,slug,city_id,name,category,summary,history_html,tips,timings,entry_fee,time_needed,best_time,closed_on,photography,nearest_station,accessibility,lat,lng,sort_rank,status) VALUES (1,'ahmedabad-fort',1,'Ahmedabad Fort','Fort','Ramparts, palaces and a view over the whole city from the top.','<p>Built in stages between the fourteenth and eighteenth centuries, the site reflects three separate periods of patronage and at least two of neglect. What survives is largely the work of the middle period, when the city was at its wealthiest.</p><p>It was brought under protection in the twentieth century, and restoration since has been conservative — consolidating what stood rather than rebuilding what had gone. That is why some sections are open to the sky.</p>','["Arrive within the first hour of opening; the light is better and the ticket queue has not formed.","Guides wait at the gate. Agree the fee and the duration before you start walking.","There is no reliable food inside. Eat before, or plan the visit around a meal nearby."]'::jsonb,'10:00 – 18:00, closed 13:00 – 14:00','₹25 Indian / ₹300 foreign','1 – 2 hours','Sunset','Closed on public holidays','Allowed outside only','Ahmedabad Junction, 7 km','Step-free at the main entrance',22.85,86.51,1,'published');
