-- Travel Roach — complete Postgres database
-- Schema, indexes, full-text search, and content.
-- Generated 2026-09-15
--
--   psql "$DATABASE_URL" -f database/travel-roach.sql
-- or paste into the Neon / Supabase SQL editor.

BEGIN;
-- ============ Enums ============
DO $$ BEGIN CREATE TYPE role AS ENUM ('admin','editor','owner','traveller'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE place_kind AS ENUM ('State','UT'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE region AS ENUM ('North','West','South','East','North-East','Central'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE section AS ENUM ('things-to-do','food','how-to-reach','nearby'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE status AS ENUM ('draft','published'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE listing_kind AS ENUM ('travel-agents','hotels','restaurants'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE media_owner AS ENUM ('library','listing','review','post'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE claim_status AS ENUM ('pending','approved','rejected'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE claim_method AS ENUM ('domain-match','manual'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE review_status AS ENUM ('published','hidden','reported'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE enquiry_status AS ENUM ('new','read','replied','spam'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;

-- ============ Tables ============
CREATE TABLE IF NOT EXISTS users (
  id SERIAL PRIMARY KEY,
  email VARCHAR(200) NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  name VARCHAR(160) NOT NULL,
  role role NOT NULL DEFAULT 'traveller',
  email_verified BOOLEAN DEFAULT FALSE,
  verify_token VARCHAR(120),
  reset_token VARCHAR(120),
  reset_expires TIMESTAMPTZ,
  avatar_id INTEGER,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  last_login_at TIMESTAMPTZ
);
CREATE UNIQUE INDEX IF NOT EXISTS users_email ON users (email);
CREATE INDEX IF NOT EXISTS users_role ON users (role);

CREATE TABLE IF NOT EXISTS sessions (
  id VARCHAR(64) PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  expires_at TIMESTAMPTZ NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS sessions_user ON sessions (user_id);

CREATE TABLE IF NOT EXISTS media (
  id SERIAL PRIMARY KEY,
  filename VARCHAR(255) NOT NULL,
  path VARCHAR(400) NOT NULL,
  thumb_path VARCHAR(400),
  mime VARCHAR(80) NOT NULL,
  width INTEGER, height INTEGER, bytes INTEGER NOT NULL,
  alt VARCHAR(300), credit VARCHAR(200),
  uploaded_by INTEGER NOT NULL,
  owner_kind media_owner DEFAULT 'library',
  owner_id INTEGER, sort_order INTEGER DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS media_owner ON media (owner_kind, owner_id);
CREATE INDEX IF NOT EXISTS media_uploader ON media (uploaded_by);

CREATE TABLE IF NOT EXISTS states (
  id SERIAL PRIMARY KEY,
  slug VARCHAR(120) NOT NULL, name VARCHAR(160) NOT NULL,
  kind place_kind NOT NULL, region region NOT NULL,
  tagline VARCHAR(255), intro TEXT, quote VARCHAR(500), quote_by VARCHAR(160),
  best_season VARCHAR(80), days_needed VARCHAR(40), daily_budget VARCHAR(40),
  airports VARCHAR(255), hero_media_id INTEGER, published BOOLEAN DEFAULT TRUE
);
CREATE UNIQUE INDEX IF NOT EXISTS states_slug ON states (slug);

CREATE TABLE IF NOT EXISTS cities (
  id SERIAL PRIMARY KEY,
  slug VARCHAR(120) NOT NULL,
  state_id INTEGER NOT NULL REFERENCES states(id) ON DELETE CASCADE,
  name VARCHAR(160) NOT NULL, tagline VARCHAR(255), intro TEXT,
  best_season VARCHAR(80), days_needed VARCHAR(40), daily_budget VARCHAR(40),
  nearest_airport VARCHAR(120), hero_media_id INTEGER,
  published BOOLEAN DEFAULT FALSE
);
CREATE UNIQUE INDEX IF NOT EXISTS cities_slug ON cities (state_id, slug);
CREATE INDEX IF NOT EXISTS cities_published ON cities (published);

CREATE TABLE IF NOT EXISTS posts (
  id SERIAL PRIMARY KEY,
  slug VARCHAR(200) NOT NULL,
  city_id INTEGER REFERENCES cities(id) ON DELETE CASCADE,
  state_id INTEGER, section section NOT NULL,
  kicker VARCHAR(80), title VARCHAR(255) NOT NULL, dek VARCHAR(500),
  body_html TEXT, takeaways JSONB, hero_media_id INTEGER, author_id INTEGER,
  reading_minutes INTEGER DEFAULT 5, featured BOOLEAN DEFAULT FALSE,
  status status DEFAULT 'draft',
  published_at TIMESTAMPTZ, updated_at TIMESTAMPTZ DEFAULT NOW()
);
CREATE UNIQUE INDEX IF NOT EXISTS posts_slug ON posts (slug);
CREATE INDEX IF NOT EXISTS posts_list ON posts (city_id, section, status, published_at);

CREATE TABLE IF NOT EXISTS attractions (
  id SERIAL PRIMARY KEY,
  slug VARCHAR(200) NOT NULL,
  city_id INTEGER NOT NULL REFERENCES cities(id) ON DELETE CASCADE,
  name VARCHAR(200) NOT NULL, category VARCHAR(80), summary VARCHAR(500),
  history_html TEXT, tips JSONB, hero_media_id INTEGER,
  timings VARCHAR(160), entry_fee VARCHAR(120), time_needed VARCHAR(80),
  best_time VARCHAR(120), closed_on VARCHAR(120), photography VARCHAR(160),
  nearest_station VARCHAR(160), accessibility VARCHAR(160),
  lat NUMERIC(10,7), lng NUMERIC(10,7),
  sort_rank INTEGER DEFAULT 99,
  status status DEFAULT 'draft'
);
CREATE UNIQUE INDEX IF NOT EXISTS attractions_slug ON attractions (slug);
CREATE INDEX IF NOT EXISTS attractions_city ON attractions (city_id, sort_rank);

CREATE TABLE IF NOT EXISTS events (
  id SERIAL PRIMARY KEY,
  slug VARCHAR(200) NOT NULL,
  city_id INTEGER NOT NULL REFERENCES cities(id) ON DELETE CASCADE,
  name VARCHAR(200) NOT NULL,
  starts_on VARCHAR(20) NOT NULL, ends_on VARCHAR(20),
  venue VARCHAR(200), season VARCHAR(40),
  ticketed BOOLEAN DEFAULT FALSE, price_from VARCHAR(60), book_ahead VARCHAR(120),
  note TEXT, hero_media_id INTEGER, status status DEFAULT 'draft'
);
CREATE UNIQUE INDEX IF NOT EXISTS events_slug ON events (slug);
CREATE INDEX IF NOT EXISTS events_city ON events (city_id, starts_on);

CREATE TABLE IF NOT EXISTS packages (
  id SERIAL PRIMARY KEY,
  slug VARCHAR(200) NOT NULL,
  city_id INTEGER REFERENCES cities(id) ON DELETE CASCADE,
  state_id INTEGER, listing_id INTEGER,
  name VARCHAR(200) NOT NULL, days INTEGER NOT NULL, route VARCHAR(255), note TEXT,
  inclusions JSONB, day_plan JSONB, price_from INTEGER, hero_media_id INTEGER,
  status status DEFAULT 'draft', sort_order INTEGER DEFAULT 0
);
CREATE UNIQUE INDEX IF NOT EXISTS packages_slug ON packages (slug);
CREATE INDEX IF NOT EXISTS packages_city ON packages (city_id, days);

CREATE TABLE IF NOT EXISTS listings (
  id SERIAL PRIMARY KEY,
  slug VARCHAR(200) NOT NULL,
  city_id INTEGER NOT NULL REFERENCES cities(id) ON DELETE CASCADE,
  kind listing_kind NOT NULL,
  name VARCHAR(200) NOT NULL, meta VARCHAR(255), blurb VARCHAR(600), about_html TEXT,
  hero_media_id INTEGER,
  verified BOOLEAN DEFAULT FALSE, verified_at TIMESTAMPTZ,
  registration VARCHAR(200), established INTEGER,
  area VARCHAR(120), address VARCHAR(300), hours VARCHAR(160),
  phone VARCHAR(40), whatsapp VARCHAR(40), email VARCHAR(200), website VARCHAR(300),
  lat NUMERIC(10,7), lng NUMERIC(10,7),
  price_from INTEGER, tags JSONB, details JSONB,
  rating_cached NUMERIC(2,1) DEFAULT 0.0,
  review_count_cached INTEGER DEFAULT 0,
  views_this_month INTEGER DEFAULT 0,
  owner_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
  status status DEFAULT 'draft',
  created_at TIMESTAMPTZ DEFAULT NOW()
);
CREATE UNIQUE INDEX IF NOT EXISTS listings_slug ON listings (slug);
CREATE INDEX IF NOT EXISTS listings_browse ON listings (city_id, kind, status, rating_cached);
CREATE INDEX IF NOT EXISTS listings_owner ON listings (owner_id);

CREATE TABLE IF NOT EXISTS listing_rows (
  id SERIAL PRIMARY KEY,
  listing_id INTEGER NOT NULL REFERENCES listings(id) ON DELETE CASCADE,
  name VARCHAR(200) NOT NULL, meta VARCHAR(200), note TEXT, price VARCHAR(60),
  media_id INTEGER, sort_order INTEGER DEFAULT 0
);
CREATE INDEX IF NOT EXISTS rows_listing ON listing_rows (listing_id, sort_order);

CREATE TABLE IF NOT EXISTS claims (
  id SERIAL PRIMARY KEY,
  listing_id INTEGER NOT NULL REFERENCES listings(id) ON DELETE CASCADE,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  status claim_status DEFAULT 'pending',
  method claim_method DEFAULT 'manual',
  evidence TEXT, reviewed_by INTEGER,
  created_at TIMESTAMPTZ DEFAULT NOW(), reviewed_at TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS claims_listing ON claims (listing_id);
CREATE INDEX IF NOT EXISTS claims_status ON claims (status);

CREATE TABLE IF NOT EXISTS reviews (
  id SERIAL PRIMARY KEY,
  listing_id INTEGER NOT NULL REFERENCES listings(id) ON DELETE CASCADE,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  rating INTEGER NOT NULL, body TEXT, trip_label VARCHAR(200),
  verified_booking BOOLEAN DEFAULT FALSE,
  owner_reply TEXT, owner_replied_at TIMESTAMPTZ,
  status review_status DEFAULT 'published',
  created_at TIMESTAMPTZ DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS reviews_listing ON reviews (listing_id, status);
CREATE UNIQUE INDEX IF NOT EXISTS reviews_one_per_user ON reviews (listing_id, user_id);

CREATE TABLE IF NOT EXISTS enquiries (
  id SERIAL PRIMARY KEY,
  listing_id INTEGER REFERENCES listings(id) ON DELETE SET NULL,
  package_id INTEGER, user_id INTEGER,
  name VARCHAR(160) NOT NULL, email VARCHAR(200) NOT NULL,
  phone VARCHAR(40), travel_dates VARCHAR(120), message TEXT,
  status enquiry_status DEFAULT 'new', source_page VARCHAR(300),
  created_at TIMESTAMPTZ DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS enquiries_listing ON enquiries (listing_id, created_at);
CREATE INDEX IF NOT EXISTS enquiries_email ON enquiries (email);

CREATE TABLE IF NOT EXISTS page_views (
  id SERIAL PRIMARY KEY,
  path VARCHAR(300) NOT NULL, day VARCHAR(10) NOT NULL,
  hits INTEGER DEFAULT 1, listing_id INTEGER
);
CREATE UNIQUE INDEX IF NOT EXISTS views_path_day ON page_views (path, day);
CREATE INDEX IF NOT EXISTS views_day ON page_views (day);

-- Full-text search across posts. Postgres does this natively, so /search
-- needs no Elasticsearch.
CREATE INDEX IF NOT EXISTS posts_fts ON posts
  USING GIN (to_tsvector('english', coalesce(title,'') || ' ' || coalesce(dek,'')));
CREATE INDEX IF NOT EXISTS listings_fts ON listings
  USING GIN (to_tsvector('english', coalesce(name,'') || ' ' || coalesce(blurb,'')));

-- posts.updated_at maintained by trigger (Postgres has no ON UPDATE clause).
CREATE OR REPLACE FUNCTION touch_updated_at() RETURNS trigger AS $$
BEGIN NEW.updated_at = NOW(); RETURN NEW; END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS posts_touch ON posts;
CREATE TRIGGER posts_touch BEFORE UPDATE ON posts
  FOR EACH ROW EXECUTE FUNCTION touch_updated_at();

