-- ============ Rooms / menus / packages (116) ============

-- SERIAL sequences must be moved past the explicit ids above.
SELECT setval('states_id_seq', 35);
SELECT setval('cities_id_seq', 86);
SELECT setval('posts_id_seq', 60);
SELECT setval('attractions_id_seq', 8);
SELECT setval('events_id_seq', 12);
SELECT setval('packages_id_seq', 6);
SELECT setval('listings_id_seq', 29);
SELECT setval('listing_rows_id_seq', 116);

COMMIT;

